const $=id=>document.getElementById(id);let state=null,currentRoom=null,busy=false,roomsKey='';
const remoteMode=!['127.0.0.1','localhost','[::1]'].includes(location.hostname),publicMode=false,tokenKey='rfd-central-tab-session';
if(new URLSearchParams(location.search).get('account')==='second'){sessionStorage.removeItem(tokenKey);history.replaceState(null,'',location.pathname);}
let token=sessionStorage.getItem(tokenKey)||'';
const T=text=>window.rfdT?.(text)||text;
function notice(text){$('notice').textContent=window.rfdT?.(text)||text;$('notice').hidden=!text;}
async function api(route,body){const response=await fetch((remoteMode?'/api/realm?route='+encodeURIComponent(route):'/api/'+route),{method:body?'POST':'GET',headers:{Authorization:'Bearer '+(token||'logged-out'),...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify(body):undefined});const data=await response.json();if(!response.ok){const error=Error(data.error||'Não foi possível concluir.');error.status=response.status;throw error;}return data;}
async function action(fn){if(busy)return;busy=true;document.body.setAttribute('aria-busy','true');try{await fn();await refresh();}catch(e){notice(e.message);}finally{busy=false;document.body.setAttribute('aria-busy','false');}}
function credentials(){const values=new FormData($('login-form'));return {username:values.get('username'),password:values.get('password')};}
$('login-form').addEventListener('submit',e=>{e.preventDefault();action(async()=>{const result=await api('login',credentials());token=result.sessionToken;sessionStorage.setItem(tokenKey,token);$('login-form').reset();notice('Bem-vindo à comunidade.');});});
$('register').addEventListener('click',()=>{if($('login-form').reportValidity())action(async()=>{const result=await api('register',credentials());token=result.sessionToken;sessionStorage.setItem(tokenKey,token);$('login-form').reset();notice('Conta criada. Bem-vindo a Tristram.');});});
$('logout').addEventListener('click',()=>action(async()=>{await api('logout',{});state=null;token='';sessionStorage.removeItem(tokenKey);view('home');notice('Você saiu da conta.');}));
$('channel-form').addEventListener('submit',e=>{e.preventDefault();action(async()=>{await api('channel',{channel:new FormData(e.target).get('channel')});e.target.reset();});});
$('chat-form').addEventListener('submit',e=>{e.preventDefault();action(async()=>{await api('chat',{text:new FormData(e.target).get('text')});e.target.reset();});});
$('room-form').addEventListener('submit',e=>{e.preventDefault();action(async()=>{const values=new FormData(e.target);await api('rooms/create',{name:values.get('name'),password:values.get('password'),mode:values.get('mode'),difficulty:Number(values.get('difficulty')),contentHash:state.contentHash});e.target.reset();$('create-dialog').close();notice('Sala criada na comunidade.');});});
$('leave').addEventListener('click',()=>action(async()=>{await api('rooms/leave',{roomId:currentRoom.id});notice('Você saiu da sala.');}));
$('launch').addEventListener('click',()=>action(async()=>{const result=await api('launch',{roomId:currentRoom.id,windowedTest:$('test-window').checked});notice(result.message);if(result.launchUri&&/^rfd:\/\/(play\/[A-Za-z0-9_-]+|resume\/[a-z][a-z0-9_-]{2,15}\/[a-f0-9-]{36}(?:\?auth=[A-Za-z0-9_-]{43})?|focus)$/.test(result.launchUri))location.href=result.launchUri;}));
function element(tag,text,className){const el=document.createElement(tag);el.textContent=text;if(className)el.className=className;return el;}
async function refresh(){
  try{state=await api('state');}catch(e){if(e.status===401||e.status===403){signedOut();if(token){token='';sessionStorage.removeItem(tokenKey);}}return;}
  $('entry').hidden=true;$('signed-in').hidden=false;$('public-entry').hidden=true;$('lobby').hidden=false;$('play-login').hidden=true;$('identity').textContent=state.username;$('welcome').textContent=T('Bem-vindo,')+' '+state.username+'.';$('client-version').textContent=state.clientVersion?'v'+state.clientVersion:'Em preparação';$('chat-status').textContent=state.users.length+' '+T('no canal');$('chat-text').disabled=false;$('chat-form').querySelector('button').disabled=false;$('channel-title').textContent=state.channel||'Entrando no canal…';
  $('channels').replaceChildren(...state.channels.map(channel=>{const b=element('button',channel);b.setAttribute('aria-current',String(channel===state.channel));b.addEventListener('click',()=>action(()=>api('channel',{channel})));return b;}));
  window.RfdSanctuary?.update(state);
  currentRoom=state.rooms.find(r=>r.players.some(p=>p.user.toLowerCase()===state.username.toLowerCase()));$('membership').hidden=!currentRoom;$('home-room').textContent=currentRoom?.name||T('Nenhuma sala');$('room-count').textContent=state.rooms.length;$('show-create').disabled=!!currentRoom;
  if(currentRoom){$('room-name').textContent=currentRoom.name;$('party-slots').replaceChildren(...Array.from({length:4},(_,i)=>{const p=currentRoom.players[i],slot=element('div','','party-slot'+(p?'':' vacant'));slot.append(element('strong',p?p.user:'Lugar disponível'),element('small',p?(p.connected?'No jogo':'Na central'):'Aguardando aventureiro'));return slot;}));$('room-detail').textContent=currentRoom.name+' · '+currentRoom.players.length+'/4 · '+currentRoom.players.map(p=>p.user+(p.connected?' ('+T('cliente conectado')+')':'')).join(', ');$('launch').disabled=false;}
  if(document.activeElement?.closest('#rooms')&&document.activeElement.tagName==='INPUT')return;
  renderRooms();
}
function renderRooms(){if(!state||document.activeElement?.closest('#rooms')&&document.activeElement.tagName==='INPUT')return;const visible=state.rooms.filter(room=>!window.RfdSanctuary||window.RfdSanctuary.roomVisible(room));$('room-count').textContent=visible.length;const signature=JSON.stringify([visible,currentRoom?.id,state.profile?.unlocks?.difficulties,state.profile?.unlocks?.modes,document.documentElement.lang]);if(signature===roomsKey)return;roomsKey=signature;
  $('rooms').replaceChildren(...visible.map(room=>{const row=element('div','','room');const info=element('div','');info.append(element('strong',room.name),element('p',`${room.players.length}/4 · ${T(room.mode==='coliseum-pvp'?'Coliseum':'Campanha cooperativa')} · ${window.RfdSanctuary?.tier(room.difficulty)||'Horror'}${room.locked?' · '+T('Com senha'):''}`));row.append(info);const unlocked=(state.profile?.unlocks?.difficulties||[0]).includes(room.difficulty??0)&&(room.mode!=='coliseum-pvp'||state.profile?.unlocks?.modes?.includes(8));const button=element('button',!unlocked?T('Bloqueado'):currentRoom?.id===room.id?T('Sua sala'):T('Entrar →'),'secondary');button.disabled=!!currentRoom||room.players.length>=4||!unlocked;button.addEventListener('click',()=>{if(room.locked){$('join-title').textContent=room.name;$('join-dialog').showModal();$('join-form').onsubmit=e=>{e.preventDefault();action(async()=>{await api('rooms/join',{roomId:room.id,password:new FormData(e.target).get('password'),contentHash:state.contentHash});e.target.reset();$('join-dialog').close();});};}else action(()=>api('rooms/join',{roomId:room.id,contentHash:state.contentHash}));});row.append(button);return row;}));if(!visible.length)$('rooms').append(element('p',T('Nenhuma partida aberta. Crie a primeira jornada.'),'muted'));
}
window.rfdRenderRooms=renderRooms;window.rfdRefresh=refresh;
const handoff=/^#auth=([A-Za-z0-9_-]{43})$/.exec(location.hash);
if(handoff)history.replaceState(null,'',location.pathname+location.search+'#home');
signedOut();view(location.hash.slice(1)||'home');
(async()=>{if(handoff)await action(async()=>{const result=await api('auth/redeem',{code:handoff[1],target:'web'});token=result.sessionToken;sessionStorage.setItem(tokenKey,token);});else await refresh();refreshHealth();})();
for(const button of document.querySelectorAll('a[href="rfd://open"]'))button.addEventListener('click',e=>{if(!token)return;e.preventDefault();action(async()=>{const result=await api('auth/handoff',{target:'client'});if(/^[a-z][a-z0-9_-]{2,15}$/i.test(result.username)&&/^[A-Za-z0-9_-]{43}$/.test(result.code))location.href='rfd://auth/'+result.username.toLowerCase()+'/'+result.code;});});
setInterval(()=>{if(!busy&&!document.hidden)refresh();},1500);

function view(name){if(!/^(home|play|social|client|profile(?:\/[A-Za-z][A-Za-z0-9_-]{2,15})?)$/.test(name))name='home';const panel=name.split('/')[0];document.querySelectorAll('[data-panel]').forEach(el=>el.hidden=el.dataset.panel!==panel);document.querySelectorAll('[data-view]').forEach(el=>{const on=el.dataset.view===panel;el.classList.toggle('active',on);if(on)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});history.replaceState(null,'',location.pathname+location.search+'#'+name);window.RfdSanctuary?.onView(name);}
window.rfdView=view;window.addEventListener('hashchange',()=>view(location.hash.slice(1)||'home'));
document.querySelectorAll('[data-view],[data-go]').forEach(el=>el.addEventListener('click',()=>view(el.dataset.view||el.dataset.go)));
for(const id of ['hero-play','continue-play'])$(id).addEventListener('click',()=>{if(state)view('play');else if(publicMode)location.href='http://127.0.0.1:18092/';else{view('home');$('login-form').elements.username.focus();}});
$('account-nav').addEventListener('click',()=>{view(state?'profile':'home');if(!state&&!publicMode)$('login-form').elements.username.focus();});
for(const id of ['second-account','second-account-client'])$(id).addEventListener('click',()=>{window.open((publicMode?'http://127.0.0.1:18092':location.origin)+'/?account=second','_blank','noopener');});
document.querySelectorAll('[data-close]').forEach(el=>el.addEventListener('click',()=>$(el.dataset.close).close()));
$('show-create').addEventListener('click',()=>{if(!state){notice('Entre na sua conta para criar uma sala.');view('home');return;}if(!currentRoom){window.RfdSanctuary?.updateRoomForm();$('create-dialog').showModal();}});
$('refresh-rooms').addEventListener('click',()=>action(async()=>{await refresh();notice('Salas atualizadas.');}));
function signedOut(){state=null;currentRoom=null;$('entry').hidden=publicMode;$('signed-in').hidden=true;$('public-entry').hidden=!publicMode;$('lobby').hidden=true;$('play-login').hidden=false;$('identity').textContent=window.rfdT?.('Minha conta')||'Minha conta';$('show-create').disabled=false;$('chat-text').disabled=true;$('chat-form').querySelector('button').disabled=true;$('channels').replaceChildren();$('users').replaceChildren();$('messages').replaceChildren(element('p','Entre na sua conta para participar do bate-papo.','system'));window.RfdSanctuary?.update(null);}
async function refreshHealth(){if(publicMode){$('connection-text').textContent='Prévia da comunidade';$('realm-status').textContent='Servidor público em preparação';$('footer-status').textContent='Abra a central local para jogar';return;}try{const res=await fetch(remoteMode?'/api/realm?route=health':'/health');if(!res.ok)throw Error();const h=await res.json();$('connection-dot').classList.toggle('online',h.gatewayListening);$('connection-text').textContent=h.gatewayListening?(remoteMode?'Reino online':'Servidor local online'):'Servidor indisponível';$('realm-status').textContent=h.gatewayListening?'Tristram está à sua espera.':'O reino está offline.';$('stat-users').textContent=h.lobbySessions;$('stat-rooms').textContent=h.rooms;$('stat-playing').textContent=h.connectedGamePlayers;$('footer-status').textContent=(remoteMode?'REINO ONLINE · ATÉ ':'REINO LOCAL · ATÉ ')+h.playersPerRoom+' JOGADORES POR SALA';}catch{$('connection-dot').classList.remove('online');$('connection-text').textContent='Servidor indisponível';$('realm-status').textContent='Aguardando o servidor.';$('footer-status').textContent='CONEXÃO INTERROMPIDA';for(const id of ['stat-users','stat-rooms','stat-playing'])$(id).textContent='—';}}
setInterval(()=>{if(!document.hidden)refreshHealth();},5000);

// Keep download buttons current even when only the signed release feed changes.
(async()=>{try{const r=await fetch('/downloads/latest.json',{cache:'no-store'});if(!r.ok)return;const envelope=await r.json(),manifest=JSON.parse(new TextDecoder().decode(Uint8Array.from(atob(envelope.payload),c=>c.charCodeAt(0))));if(!/^\d+\.\d+\.\d+$/.test(manifest.version))return;const archive=new URL(manifest.archiveUrl),prefix='/VagJr/returns-from-darkness/releases/download/client-v'+manifest.version+'/';if(archive.protocol!=='https:'||archive.hostname!=='github.com'||!archive.pathname.startsWith(prefix))return;for(const button of document.querySelectorAll('[data-client-download]'))button.href='https://github.com'+prefix+'ReturnsFromDarkness-Setup.exe';const version=document.getElementById('download-version');if(version)version.textContent='v'+manifest.version;}catch{}})();
